SSCTurtleQuestText[41416] = {
    accept = "I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us. That is why the price is so high. If I'm going to die, it's going to be as a rich man.$B$BAnd I don't give an ounce of gnoll spit how you die, only that you do as I ask. Bring me the ring we will both benefit - or die; but I've already explained this...",
    progress = "The prodigal rodent returns! Have you found it?",
    complete = "Do you see? Do you now understand the power? Purification... What fools…$B$B<Mataus shakes his head disapprovingly.>$B$BNow take it and get out of my sight.",
}
SSCTurtleQuestText[41417] = {
    accept = "You don the Nemesis garments, $C. I can feel the darkness loom around you, yet it seems rather dim. Perhaps the ones you carry are not suited for the tasks you are willing to perform.$B$B<Melus hums for a few seconds.>$B$BHand it here and tell me, are demons chatty?",
    progress = "Choose carefully, your decision is final.",
    complete = "These garments seem to suit your true nature far better. Be mindful of the power you possess, $C.",
}
