SSCTurtleQuestText[41433] = {
    accept = "During your battles with the Scourge in Naxxramas, should you come across a desecrated ring, return it to me and I shall forge it into something better suited for you.",
    progress = "Korfax knows what he's doing.",
    complete = "If you lose your weapon in battle, a punch while wearing this will prove more than efficient.",
}
