SSCTurtleQuestText[41484] = {
    accept = "You will find the remnants of our fallen heroes on the corpses of the Lords of Naxxramas. Bring those desecrated keepsakes to me were they not to suit your needs and I will provide an alternative.",
    progress = "I hope you chose well, I will not be returning the other ring.",
    complete = "Make your choice.",
}
