SSCTurtleQuestText[41507] = {
    accept = "You have claimed the garments of the Ten Storms, $C. I can sense the will of the elements and your might, yet it seems rather dim. Perhaps the ones you carry are not suited for the tasks you are willing to perform.$B$B<Kazud hums for a few seconds.>$B$BHand it here and tell me, how should the elements aid you?",
    progress = "Choose carefully, your decision is final.",
    complete = "The Elements dance around you in anticipation and joy, may their might become your own.",
}
